INSERT INTO skill_levels (skill_id, level, label, description) SELECT id, 5, 'Authority', 'Industry-recognised authority in ServiceNow. Publishes, speaks, teaches, or sets standards. Shapes how ServiceNow is understood and applied at a field level.' FROM skills WHERE taxonomy_key = 'servicenow' ON CONFLICT (skill_id, level) DO UPDATE SET label = EXCLUDED.label, description = EXCLUDED.description;
